98	    {
99	        var attributeNames = await db.Subcategories
100	            .Where(s => s.Id == subcategoryId)
101	            .Select(s => s.AttributeNames)
102	            .FirstOrDefaultAsync();
103	
104	        if (attributeNames is null || attributeNames.Count == 0)
