126	            var values = distinctValues.All(v => decimal.TryParse(v, NumberStyles.Number, CultureInfo.InvariantCulture, out _))
127	                ? distinctValues.OrderBy(v => decimal.Parse(v, NumberStyles.Number, CultureInfo.InvariantCulture)).ToList()
128	                : distinctValues.OrderBy(v => v, StringComparer.Ordinal).ToList();
129	            result.Add(new AttributeFilterOptionDto(name, values));
